From e9eed8c0e8c2d55592a659af259974a45922bdcc Mon Sep 17 00:00:00 2001
From: Bron Gondwana <brong@fastmail.fm>
Date: Tue, 28 Aug 2018 01:29:55 +1000
Subject: [PATCH] mailbox: bump the counters when we bump the modseq!

This fixes a bug introduced in bbe312e6501f3a8778ab032d1620e7d1764aea7e
where mboxevents would have a counter value which had the earlier
values than the modseq on the actual records.

diff --git a/imap/mailbox.c b/imap/mailbox.c
index 2aff647ab..700c4165f 100644
--- a/imap/mailbox.c
+++ b/imap/mailbox.c
@@ -1064,14 +1064,12 @@ EXPORTED modseq_t mailbox_modseq_dirty(struct mailbox *mailbox)
     if (mailbox->silentchanges)
         return mailbox->i.highestmodseq;

-    if (!mailbox->modseq_dirty) {
-        mailbox->i.highestmodseq = mboxname_setmodseq(mailbox->name,
+    mailbox->i.highestmodseq = mboxname_nextmodseq(mailbox->name,
                                    mailbox->i.highestmodseq,
                                    mailbox->mbtype, /*dofolder*/0);
-        mailbox->last_updated = time(0);
-        mailbox->modseq_dirty = 1;
-        mailbox_index_dirty(mailbox);
-    }
+    mailbox->last_updated = time(0);
+    mailbox->modseq_dirty = 1;
+    mailbox_index_dirty(mailbox);

     mailbox->i.highestmodseq++;

@@ -2641,10 +2639,6 @@ EXPORTED int mailbox_commit(struct mailbox *mailbox)
     if (!mailbox->i.dirty)
         return 0;

-    mboxname_setmodseq(mailbox->name,
-                       mailbox->i.highestmodseq,
-                       mailbox->mbtype, /*dofolder*/0);
-
     assert(mailbox_index_islocked(mailbox, 1));

     r = _commit_changes(mailbox);
-- 
2.25.1

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
mailbox: bump the counters when we bump the modseq!

This fixes a bug introduced in bbe312e6501f3a8778ab032d1620e7d1764aea7e
where mboxevents would have a counter value which had the earlier
values than the modseq on the actual records.

Here is the root cause:
The bug was caused by the incorrect handling of the modification sequence (modseq) in the `mailbox_modseq_dirty` function, where the counters for mailbox events were not being updated correctly when the modseq was incremented. This led to a situation where the event counters had earlier values than the actual modseq, resulting in inconsistencies in the mailbox state. The previous logic did not ensure that the modseq was updated properly when marking the mailbox as dirty, which was essential for maintaining synchronization between the modseq and the event counters.

Here is the patch:

 EXPORTED modseq_t mailbox_modseq_dirty(struct mailbox *mailbox)
 {
     assert(mailbox_index_islocked(mailbox, 1));

     if (mailbox->silentchanges)
         return mailbox->i.highestmodseq;

-    if (!mailbox->modseq_dirty) {
-        mailbox->i.highestmodseq = mboxname_setmodseq(mailbox->name,
+    mailbox->i.highestmodseq = mboxname_nextmodseq(mailbox->name,
                                    mailbox->i.highestmodseq,
                                    mailbox->mbtype, /*dofolder*/0);
-        mailbox->last_updated = time(0);
-        mailbox->modseq_dirty = 1;
-        mailbox_index_dirty(mailbox);
-    }
+    mailbox->last_updated = time(0);
+    mailbox->modseq_dirty = 1;
+    mailbox_index_dirty(mailbox);

     mailbox->i.highestmodseq++;

     return mailbox->i.highestmodseq;
 }

  */
 EXPORTED int mailbox_commit(struct mailbox *mailbox)
 {
     /* XXX - ibuf for alignment? */
     static unsigned char buf[INDEX_HEADER_SIZE];
     int n, r;

     /* try to commit sub parts first */
 #ifdef WITH_DAV
     r = mailbox_commit_dav(mailbox);
     if (r) return r;
 #endif

     r = mailbox_commit_cache(mailbox);
     if (r) return r;

     r = mailbox_commit_quota(mailbox);
     if (r) return r;

     r = annotate_state_commit(&mailbox->annot_state);
     if (r) return r;

     r = mailbox_commit_header(mailbox);
     if (r) return r;

     if (!mailbox->i.dirty)
         return 0;

-    mboxname_setmodseq(mailbox->name,
-                       mailbox->i.highestmodseq,
-                       mailbox->mbtype, /*dofolder*/0);
-
     assert(mailbox_index_islocked(mailbox, 1));

     r = _commit_changes(mailbox);
     if (r) return r;

     /* always update xconvmodseq, it might have been done by annotations */
     r = mailbox_update_xconvmodseq(mailbox, mailbox->i.highestmodseq, /*force*/0);
     if (r) return r;

     mailbox_index_header_to_buf(&mailbox->i, buf);

     lseek(mailbox->index_fd, 0, SEEK_SET);
     n = retry_write(mailbox->index_fd, buf, mailbox->i.start_offset);
     if (n < 0 || fsync(mailbox->index_fd)) {
         syslog(LOG_ERR, "IOERROR: writing index header for %s: %m",
                mailbox->name);
         return IMAP_IOERROR;
     }

     if (config_auditlog && mailbox->modseq_dirty)
         syslog(LOG_NOTICE, "auditlog: modseq sessionid=<%s> "
                "mailbox=<%s> uniqueid=<%s> highestmodseq=<" MODSEQ_FMT ">",
             session_id(), mailbox->name, mailbox->uniqueid,
             mailbox->i.highestmodseq);

     /* remove all dirty flags! */
     mailbox->i.dirty = 0;
     mailbox->modseq_dirty = 0;
     mailbox->header_dirty = 0;

     /* label changes for later logging */
     mailbox->has_changed = 1;

     return 0;
 }



